// Pure JS SHA-256 (scratch validation copy). No platform hashing module used.

// K constants derived: first 32 bits of the fractional parts of the cube roots
// of the first 64 primes. We derive them here to PROVE the derivation rule,
// then compare against the hardcoded FIPS 180-4 table.
export function deriveK() {
  const out = [];
  let n = 2;
  while (out.length < 64) {
    let isPrime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { isPrime = false; break; }
    if (isPrime) {
      // cube root fractional part * 2^32, truncated
      const c = Math.cbrt(n);
      const frac = c - Math.floor(c);
      out.push(Math.floor(frac * 4294967296) >>> 0);
    }
    n++;
  }
  return out;
}

export function deriveH() {
  const out = [];
  let n = 2;
  while (out.length < 8) {
    let isPrime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { isPrime = false; break; }
    if (isPrime) {
      const c = Math.sqrt(n);
      const frac = c - Math.floor(c);
      out.push(Math.floor(frac * 4294967296) >>> 0);
    }
    n++;
  }
  return out;
}

export const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

export const H0 = new Uint32Array([
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]);

const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

export function sha256(bytes) {
  const H = new Uint32Array(H0);
  const len = bytes.length;
  const bitLenLo = (len * 8) >>> 0;             // low 32 bits (len*8 may exceed 2^32)
  const bitLenHi = Math.floor((len * 8) / 4294967296) >>> 0;
  // padded length: len + 1 + padZeros + 8, multiple of 64
  const totalLen = (((len + 9) + 63) & ~63) >>> 0;
  const M = new Uint8Array(totalLen);
  M.set(bytes, 0);
  M[len] = 0x80;
  // 64-bit big-endian bit length in the last 8 bytes
  M[totalLen - 8] = (bitLenHi >>> 24) & 0xff;
  M[totalLen - 7] = (bitLenHi >>> 16) & 0xff;
  M[totalLen - 6] = (bitLenHi >>> 8) & 0xff;
  M[totalLen - 5] = bitLenHi & 0xff;
  M[totalLen - 4] = (bitLenLo >>> 24) & 0xff;
  M[totalLen - 3] = (bitLenLo >>> 16) & 0xff;
  M[totalLen - 2] = (bitLenLo >>> 8) & 0xff;
  M[totalLen - 1] = bitLenLo & 0xff;

  const W = new Uint32Array(64);
  for (let off = 0; off < totalLen; off += 64) {
    for (let t = 0; t < 16; t++) {
      W[t] = ((M[off + 4 * t] << 24) | (M[off + 4 * t + 1] << 16) |
              (M[off + 4 * t + 2] << 8) | M[off + 4 * t + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const w15 = W[t - 15], w2 = W[t - 2];
      const s0 = (rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3)) >>> 0;
      const s1 = (rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10)) >>> 0;
      W[t] = (((W[t - 16] + s0) >>> 0) + ((W[t - 7] + s1) >>> 0)) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const T1 = (((((h + S1) >>> 0) + ch) >>> 0) + ((K[t] + W[t]) >>> 0)) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const T2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e;
      e = (d + T1) >>> 0;
      d = c; c = b; b = a;
      a = (T1 + T2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32);
  for (let i = 0; i < 8; i++) {
    out[4 * i] = (H[i] >>> 24) & 0xff;
    out[4 * i + 1] = (H[i] >>> 16) & 0xff;
    out[4 * i + 2] = (H[i] >>> 8) & 0xff;
    out[4 * i + 3] = H[i] & 0xff;
  }
  return out;
}

export function hmacSha256(key, msg) {
  const BLOCK = 64;
  let k = key;
  if (k.length > BLOCK) k = sha256(k);
  const kpad = new Uint8Array(BLOCK); // zero-filled => right zero padding
  kpad.set(k, 0);
  const ipad = new Uint8Array(BLOCK + msg.length);
  for (let i = 0; i < BLOCK; i++) ipad[i] = kpad[i] ^ 0x36;
  ipad.set(msg, BLOCK);
  const inner = sha256(ipad);
  const opad = new Uint8Array(BLOCK + 32);
  for (let i = 0; i < BLOCK; i++) opad[i] = kpad[i] ^ 0x5c;
  opad.set(inner, BLOCK);
  return sha256(opad);
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
export function base64url(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i + 1], b2 = bytes[i + 2];
    s += B64[b0 >>> 2];
    s += B64[((b0 & 0x03) << 4) | ((b1 === undefined ? 0 : b1) >>> 4)];
    s += b1 === undefined ? '' : B64[((b1 & 0x0f) << 2) | ((b2 === undefined ? 0 : b2) >>> 6)];
    s += b2 === undefined ? '' : B64[b2 & 0x3f];
  }
  return s.replace(/\+/g, '-').replace(/\//g, '_');
}

export const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
export const asciiBytes = (s) => { const a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i) & 0xff; return a; };

import { sha256, hmacSha256, base64url, hex, asciiBytes, K, H0, deriveK, deriveH } from './sha256.mjs';

// 1. Verify K derivation matches the FIPS table
const dk = deriveK();
let kOk = true;
for (let i = 0; i < 64; i++) if ((dk[i] >>> 0) !== K[i]) { kOk = false; console.log('K mismatch at', i, dk[i].toString(16), K[i].toString(16)); }
console.log('K derivation matches FIPS table:', kOk);

const dh = deriveH();
let hOk = true;
for (let i = 0; i < 8; i++) if ((dh[i] >>> 0) !== H0[i]) { hOk = false; console.log('H mismatch at', i, dh[i].toString(16), H0[i].toString(16)); }
console.log('H derivation matches FIPS table:', hOk);

// 2. Classic vectors
const check = (label, got, want) => console.log((got === want ? 'PASS' : 'FAIL') + '  ' + label + '  ' + got + (got === want ? '' : '  want=' + want));

check('sha256("")', hex(sha256(asciiBytes(''))), 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
check('sha256("abc")', hex(sha256(asciiBytes('abc'))), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
check('sha256(448-bit 2-block msg)', hex(sha256(asciiBytes('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))), '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');
check('sha256(896-bit)', hex(sha256(asciiBytes('abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu'))), 'cf5b16a778af8380036ce59e7b0492370b249b11e8f07a51afac45037afee9d1');
const million = new Uint8Array(1000000).fill(0x61);
check('sha256("a"*1000000)', hex(sha256(million)), 'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0');

// 3. Length boundary vectors — input is 'a' repeated N
console.log('\n--- SHA-256 of "a"*N (length boundary sweep) ---');
for (const n of [0,1,54,55,56,57,63,64,65,118,119,120,121,127,128,129,191,192]) {
  const b = new Uint8Array(n).fill(0x61);
  console.log('N=' + String(n).padStart(3) + '  ' + hex(sha256(b)));
}

// 4. RFC 4231 HMAC-SHA-256 test cases
console.log('\n--- RFC 4231 HMAC-SHA-256 ---');
const hexToBytes = (h) => { const a = new Uint8Array(h.length / 2); for (let i = 0; i < a.length; i++) a[i] = parseInt(h.substr(2*i,2),16); return a; };
const tcs = [
  { n:1, key: hexToBytes('0b'.repeat(20)), msg: asciiBytes('Hi There'), want:'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7' },
  { n:2, key: asciiBytes('Jefe'), msg: asciiBytes('what do ya want for nothing?'), want:'5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843' },
  { n:3, key: hexToBytes('aa'.repeat(20)), msg: hexToBytes('dd'.repeat(50)), want:'773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe' },
  { n:4, key: hexToBytes('0102030405060708090a0b0c0d0e0f10111213141516171819'), msg: hexToBytes('cd'.repeat(50)), want:'82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b' },
  { n:5, key: hexToBytes('0c'.repeat(20)), msg: asciiBytes('Test With Truncation'), want:'a3b6167473100ee06e0c796c2955552bfa6f7c0a6a8aef8b93f860aab0cd20c5', trunc:16 },
  { n:6, key: hexToBytes('aa'.repeat(131)), msg: asciiBytes('Test Using Larger Than Block-Size Key - Hash Key First'), want:'60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54' },
  { n:7, key: hexToBytes('aa'.repeat(131)), msg: asciiBytes('This is a test using a larger than block-size key and a larger than block-size data. The key needs to be hashed before being used by the HMAC algorithm.'), want:'9b09ffa71b942fcb27635fbcd5b0e944bfdc63644f0713938a7f51535c3a35e2' },
];
for (const t of tcs) {
  let got = hex(hmacSha256(t.key, t.msg));
  if (t.trunc) got = got.slice(0, t.trunc * 2);
  check('RFC4231 TC' + t.n, got, t.want);
}

// 5. base64url sanity
console.log('\n--- base64url ---');
console.log('b64url(bytes 0..5):', base64url(new Uint8Array([0,1,2,3,4,5])));
console.log('b64url("f"):', base64url(asciiBytes('f')), '(expect Zg)');
console.log('b64url("fo"):', base64url(asciiBytes('fo')), '(expect Zm8)');
console.log('b64url("foo"):', base64url(asciiBytes('foo')), '(expect Zm9v)');
console.log('b64url(0xfb,0xff,0xfe):', base64url(new Uint8Array([0xfb,0xff,0xfe])), '(expect -_-- style: exercises - and _)');
console.log('b64url(0xff,0xef,0xfe):', base64url(new Uint8Array([0xff,0xef,0xfe])));

import { sha256, hmacSha256, base64url, hex, asciiBytes } from './sha256.mjs';

// Full untruncated TC5
const hexToBytes = (h) => { const a = new Uint8Array(h.length / 2); for (let i = 0; i < a.length; i++) a[i] = parseInt(h.substr(2*i,2),16); return a; };
console.log('RFC4231 TC5 FULL (untruncated) =', hex(hmacSha256(hexToBytes('0c'.repeat(20)), asciiBytes('Test With Truncation'))));

// Python-compatible json.dumps escaping (ensure_ascii, compact)
const ESC = { 0x08:'\\b', 0x09:'\\t', 0x0a:'\\n', 0x0c:'\\f', 0x0d:'\\r', 0x22:'\\"', 0x5c:'\\\\' };
export function pyJsonString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ESC[cp] !== undefined) { out += ESC[cp]; continue; }
    if (cp >= 0x20 && cp <= 0x7e) { out += ch; continue; }
    if (cp > 0xffff) {
      const v = cp - 0x10000;
      out += '\\u' + (0xd800 + (v >> 10)).toString(16).padStart(4,'0');
      out += '\\u' + (0xdc00 + (v & 0x3ff)).toString(16).padStart(4,'0');
    } else {
      out += '\\u' + cp.toString(16).padStart(4,'0');
    }
  }
  return out + '"';
}

const utf8 = (s) => { const a = []; for (const ch of s) { let cp = ch.codePointAt(0);
  if (cp < 0x80) a.push(cp);
  else if (cp < 0x800) a.push(0xc0|(cp>>6), 0x80|(cp&63));
  else if (cp < 0x10000) a.push(0xe0|(cp>>12), 0x80|((cp>>6)&63), 0x80|(cp&63));
  else a.push(0xf0|(cp>>18), 0x80|((cp>>12)&63), 0x80|((cp>>6)&63), 0x80|(cp&63)); }
  return new Uint8Array(a); };

const HEADER_JSON = '{"alg":"HS256","typ":"JWT"}';
const HEADER_SEG = base64url(asciiBytes(HEADER_JSON));

export function makeToken(payload) {
  const payloadJson = '{"data":' + pyJsonString(payload) + '}';
  const payloadSeg = base64url(utf8(payloadJson));
  const signingInput = HEADER_SEG + '.' + payloadSeg;
  const sig = hmacSha256(asciiBytes('my_secret_key'), asciiBytes(signingInput));
  return { token: signingInput + '.' + base64url(sig), signingInput, len: signingInput.length, payloadSeg, payloadJson };
}

console.log('HEADER_SEG =', HEADER_SEG, 'len =', HEADER_SEG.length);

// Find payload lengths (plain ASCII 'a'*v) that produce target signing-input lengths L mod 64
const targets = {};
for (let v = 0; v <= 400; v++) {
  const p = 'a'.repeat(v);
  const L = makeToken(p).len;
  const m = L % 64;
  if (!targets[m]) targets[m] = [];
  targets[m].push({ v, L });
}
console.log('\n-- reachable L mod 64 residues (with ASCII payload) --');
for (const m of Object.keys(targets).map(Number).sort((a,b)=>a-b)) {
  console.log('mod', String(m).padStart(2), '->', targets[m].slice(0,3).map(x=>`v=${x.v}/L=${x.L}`).join(' '));
}

import { execFileSync } from 'node:child_process';
import { makeToken } from './e2e.mjs';

const BIN = '/workspace/dataset/test1_executable';

const cases = [];
// Boundary sweep: L (signing input length) from 52..200 for every reachable v
for (let v = 0; v <= 130; v++) cases.push('a'.repeat(v));
// Non-ASCII / escape cases to shift lengths and exercise escaping
cases.push('é', '中', '\u{1F600}', 'a"b', 'a\\b', 'a\nb', '\x00', '\x7f', 'a/b', '');

let pass = 0, fail = 0;
const failures = [];
for (const p of cases) {
  const mine = makeToken(p);
  let got;
  try {
    got = execFileSync(BIN, ['--payload', p], { encoding: 'utf8' });
  } catch (e) { failures.push([p, 'EXEC ERROR ' + e.message]); fail++; continue; }
  got = got.replace(/\n$/, '');
  if (got === mine.token) pass++;
  else { fail++; failures.push([JSON.stringify(p), 'L=' + mine.len, 'mine=' + mine.token, 'bin =' + got]); }
}
console.log('PASS', pass, 'FAIL', fail);
for (const f of failures.slice(0, 10)) console.log(f.join('\n  '));

import { execFileSync } from 'node:child_process';
import { makeToken } from './e2e.mjs';
const BIN = '/workspace/dataset/test1_executable';

// Pick one payload per interesting signing-input length L.
// Inner HMAC message length = 64 + L, so the SHA-256 padding boundary
// (extra block needed) lands at L % 64 == 55 -> 56.
const wanted = [52,53,55,56,57,59,60,63,64,65,67,116,117,119,120,121,123,127,128,180,183,184,185];
const byL = new Map();
for (let v = 0; v <= 200; v++) {
  const p = 'a'.repeat(v);
  const L = makeToken(p).len;
  if (wanted.includes(L) && !byL.has(L)) byL.set(L, p);
}

const rows = [];
for (const L of wanted) {
  const p = byL.get(L);
  if (p === undefined) { console.log('unreachable L=' + L); continue; }
  const out = execFileSync(BIN, ['--payload', p], { encoding: 'utf8' }).replace(/\n$/, '');
  const mine = makeToken(p);
  const innerLen = 64 + L;
  const innerBlocks = Math.ceil((innerLen + 9) / 64);
  rows.push({ L, innerLen, innerBlocks, vlen: p.length, payload: p, token: out, match: out === mine.token });
}
for (const r of rows) {
  console.log(`L=${String(r.L).padStart(3)} L%64=${String(r.L%64).padStart(2)} innerMsg=${String(r.innerLen).padStart(3)}B blocks=${r.innerBlocks} payloadLen=${String(r.vlen).padStart(3)} match=${r.match}`);
  console.log(`   payload: 'a'*${r.vlen}`);
  console.log(`   token:   ${r.token}`);
}
console.log('\nALL MATCH:', rows.every(r => r.match), ' count=', rows.length);

// A few non-repetitive / escaping vectors too
console.log('\n--- misc vectors ---');
for (const p of ['', 'test_data_4', 'é', '中', '\u{1F600}', 'a"b\\c', 'x\ty\nz', '\x7f', 'a/b']) {
  const out = execFileSync(BIN, ['--payload', p], { encoding: 'utf8' }).replace(/\n$/, '');
  const m = makeToken(p);
  console.log(JSON.stringify(p), 'L=' + m.len, 'match=' + (out === m.token));
  console.log('   json:  ' + m.payloadJson);
  console.log('   token: ' + out);
}

